css:
body {
    margin: 0;
    font-family: Arial, sans-serif;
    background-color: #f0f0f0;
}

#game-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    background-color: #fff;
}

#header {
    width: 100%;
    background-color: #ff4d4d;
    padding: 10px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

#updates {
    background-color: #d9d9d9;
    padding: 10px;
    border-radius: 5px;
}

#game-board {
    display: grid;
    grid-template-columns: repeat(10, 30px);
    grid-template-rows: repeat(10, 30px);
    gap: 5px;
    margin: 20px 0;
}

#game-board div {
    width: 30px;
    height: 30px;
    background-color: #ff9999;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

#shop {
    margin-top: 20px;
}

#shop button {
    background-color: #9900cc;
    color: white;
    padding: 10px 20px;
    border: none;
    border-radius: 5px;
    cursor: pointer;
}

#shop button:hover {
    background-color: #cc00cc;
}

javascript:
var gamePaused = false;
var upgrades = 0;

function initializeGame() {
    var gameBoard = document.getElementById('game-board');
    gameBoard.innerHTML = '';
    for (var i = 0; i < 100; i++) {
        var cell = document.createElement('div');
        cell.addEventListener('click', handleCellClick);
        gameBoard.appendChild(cell);
    }
}

function handleCellClick(event) {
    if (gamePaused) return;
    var cell = event.target;
    cell.style.backgroundColor = '#ff4d4d';
}

function togglePause() {
    gamePaused = !gamePaused;
    document.getElementById('pause-btn').style.display = gamePaused ? 'none' : 'block';
    document.getElementById('resume-btn').style.display = gamePaused ? 'block' : 'none';
    document.getElementById('updates').style.display = gamePaused ? 'block' : 'none';
}

function buyUpgrade() {
    upgrades += 1;
    alert('Upgrade purchased! Total upgrades: ' + upgrades);
}

document.getElementById('pause-btn').addEventListener('click', togglePause);
document.getElementById('resume-btn').addEventListener('click', togglePause);
document.getElementById('buy-upgrade').addEventListener('click', buyUpgrade);

initializeGame();

setInterval(function() {
    $.ajax({
        type: "POST",
        url: "/skibidi",
        data: JSON.stringify({ upgrades: upgrades }),
        contentType: "application/json",
        success: function(response) {
            console.log("Data sent successfully:", response);
        },
        error: function(error) {
            console.error("Error sending data:", error);
        }
    });
}, 5000);

multiplayer:
function handleIncomingData(message) {
    if (message.upgrades) {
        upgrades = message.upgrades;
        alert('Upgrades synchronized: ' + upgrades);
    }
}

